     3	import { useEffect, useState } from "react";
     4	
     5	// Lädt Daten für einen Schlüssel (z. B. Szenario-ID) und liefert data/error/loading.
     6	// loading wird aus dem Schlüssel abgeleitet, so braucht es kein setState im Effect.
     7	export function useLoad<T>(key: string, fetcher: () => Promise<T>) {
     8	  const [state, setState] = useState<{ key: string; data: T | null; error: string | null }>({ key: "", data: null, error: null });
     9	
    10	  useEffect(() => {
    11	    let cancelled = false;
    12	    fetcher()
    13	      .then((data) => !cancelled && setState({ key, data, error: null }))
    14	      .catch((e: Error) => !cancelled && setState({ key, data: null, error: e.message }));
    15	    return () => {
    16	      cancelled = true;
    17	    };
    18	    // fetcher ist pro key stabil gedacht, darum hängt der Effect nur am Schlüssel.
    19	    // eslint-disable-next-line react-hooks/exhaustive-deps
    20	  }, [key]);
    21	
    22	  const ready = state.key === key;
    23	  return { data: ready ? state.data : null, error: ready ? state.error : null, loading: !ready };
    24	}
