     8	
     9	function RankDelta({ oldRank, newRank }: { oldRank?: number; newRank: number }) {
    10	  if (!oldRank || oldRank === newRank) return null;
    11	  const movedUp = oldRank > newRank;
    12	  return (
    13	    <span className={`text-xs font-semibold ${movedUp ? "text-emerald-700" : "text-[var(--m-red)]"}`}>
    14	      {movedUp ? "▲" : "▼"} {Math.abs(oldRank - newRank)}
    15	    </span>
    16	  );
    17	}
    18	
    19	// FLIP-Animation (First, Last, Invert, Play): wir merken die Zeilenpositionen vor dem Neuordnen,
    20	// verschieben jede Zeile optisch zurück an den alten Platz und lassen sie dann gleiten.
    21	// Warum: Der Rangwechsel nach "Apply" ist der beste Demo-Moment, die Jury soll ihn sehen.
    22	function useFlip(requirements: Requirement[], animateRanks: boolean) {
    23	  const rowRefs = useRef(new Map<string, HTMLTableRowElement>());
    24	  const lastTops = useRef(new Map<string, number>());
    25	
    26	  useLayoutEffect(() => {
    27	    const reduce = window.matchMedia("(prefers-reduced-motion: reduce)").matches;
    28	    rowRefs.current.forEach((el, id) => {
    29	      el.getAnimations().forEach(animation => animation.cancel());
    30	      const top = el.getBoundingClientRect().top;
    31	      const before = lastTops.current.get(id);
    32	      if (animateRanks && !reduce && before !== undefined && Math.abs(before - top) > 1) {
    33	        el.animate(
    34	          [{ transform: `translateY(${before - top}px)` }, { transform: "translateY(0)" }],
    35	          { duration: 600, easing: "cubic-bezier(0.22, 1, 0.36, 1)" },
    36	        );
    37	      }
    38	      lastTops.current.set(id, top);
    39	    });
    40	  }, [requirements, animateRanks]);
    41	
    42	  return (id: string) => (el: HTMLTableRowElement | null) => {
    43	    if (el) rowRefs.current.set(id, el);
    44	    else rowRefs.current.delete(id);
    45	  };
    46	}
    47	
    48	// Nur vier Spalten: Rang, was, wie wichtig, wie gut belegt. Status und Konflikt-Details
    49	// stehen auf der Detailseite; ein Konflikt zeigt sich hier nur als kleines Warnzeichen.
    50	export function RequirementsTable({
    51	  requirements,
    52	  previousRanks,
    53	  highlightRanks,
    54	  conflictTitles,
    55	  scenarioId,
    56	}: {
    57	  requirements: Requirement[];
    58	  previousRanks: Record<string, number>;
    59	  highlightRanks: boolean;
    60	  conflictTitles: (r: Requirement) => string[];
    61	  scenarioId: string;
    62	}) {
    63	  const router = useRouter();
    64	  const rowRef = useFlip(requirements, highlightRanks);
    65	  const open = (id: string) => router.push(`/requirements/${id}?scenario=${encodeURIComponent(scenarioId)}`);
    66	
    67	  return (
    68	    <div className="overflow-x-auto border-t border-[var(--hairline)]">
    69	      <table className="w-full min-w-[640px] text-left text-sm">
    70	        <thead className="text-xs uppercase tracking-[0.12em] text-[var(--grey-500)]">
    71	          <tr className="border-b border-[var(--hairline)]">
    72	            {["Rank", "Requirement", "Score", "Evidence"].map((h) => (
    73	              <th key={h} className="px-4 py-3 font-semibold">{h}</th>
    74	            ))}
    75	          </tr>
    76	        </thead>
    77	        <tbody>
    78	          {requirements.map((req) => {
    79	            const moved = highlightRanks && previousRanks[req.id] !== undefined && previousRanks[req.id] !== req.rank;
    80	            return (
    81	              <tr
    82	                key={req.id}
    83	                ref={rowRef(req.id)}
    84	                role="link"
    85	                tabIndex={0}
    86	                onClick={() => open(req.id)}
    87	                onKeyDown={(e) => {
    88	                  if (e.key === "Enter" || e.key === " ") {
    89	                    e.preventDefault();
    90	                    open(req.id);
    91	                  }
    92	                }}
    93	                className={`group cursor-pointer border-b border-[var(--hairline)] transition-colors hover:bg-[var(--grey-100)] focus:bg-[var(--grey-100)] ${
    94	                  moved ? "bg-[#eef4fc]" : "bg-white"
    95	                }`}
    96	              >
    97	                <td className="w-24 px-4 py-5 align-top">
    98	                  <div className="flex items-baseline gap-2">
    99	                    <span className="text-3xl font-light tabular-nums text-[var(--ink)]">{req.rank}</span>
   100	                    <RankDelta oldRank={previousRanks[req.id]} newRank={req.rank} />
