    33	// Weight changes as "Customer pain 20% -> 25%" instead of raw JSON with float noise.
    34	function NumberChanges({ before, after }: { before: NumberMap; after: NumberMap }) {
    35	  const keys = [...new Set([...Object.keys(before), ...Object.keys(after)])];
    36	  return <ul className="grid gap-1">{keys.map(k => {
    37	    const changed = pct(before[k]) !== pct(after[k]);
    38	    return <li key={k} className={`flex justify-between gap-3 ${changed ? "font-semibold text-[var(--ink)]" : "text-[var(--grey-500)]"}`}>
    39	      <span>{k.replaceAll("_", " ")}</span><span className="tabular-nums">{pct(before[k])} &rarr; {pct(after[k])}</span>
