     1	import type { EvidenceLevel, ScoreFactor, WaterfallStep } from "@/src/lib/api";
     2	
     3	const FACTOR_ORDER = [
     4	  "customer_pain",
     5	  "reach",
     6	  "satisfaction_gap",
     7	  "competitive_pressure",
     8	  "future_relevance",
     9	  "effort_inverse",
    10	] as const;
    11	
    12	const FACTOR_LABELS: Record<string, string> = {
    13	  customer_pain: "Customer pain",
    14	  reach: "Reach",
    15	  satisfaction_gap: "Satisfaction gap",
    16	  competitive_pressure: "Competitive pressure",
    17	  future_relevance: "Future relevance",
    18	  effort_inverse: "Low effort",
    19	};
    20	
    21	const CONFIDENCE: Record<EvidenceLevel, number> = { A: 1, B: 0.85, C: 0.7, D: 0.5 };
    22	const EVIDENCE_LABEL: Record<EvidenceLevel, string> = {
    23	  A: "A · strong",
    24	  B: "B · medium",
    25	  C: "C · weak",
    26	  D: "D · assumption",
    27	};
    28	
    29	function fromBreakdown(scoreBreakdown: Record<string, ScoreFactor>): WaterfallStep[] {
    30	  const known = new Set<string>(FACTOR_ORDER);
    31	  const orderedKeys = [
    32	    ...FACTOR_ORDER.filter((key) => key in scoreBreakdown),
    33	    ...Object.keys(scoreBreakdown).filter((key) => !known.has(key)),
    34	  ];
    35	  return orderedKeys.map((key) => ({
    36	    factor: key,
    37	    label: FACTOR_LABELS[key] ?? key,
    38	    value: scoreBreakdown[key].value,
    39	    weight: scoreBreakdown[key].weight,
    40	    contribution: scoreBreakdown[key].contribution,
    41	    sentence: scoreBreakdown[key].explanation,
    42	  }));
    43	}
    44	
    45	export function scoreWithoutAssumptions(
    46	  scoreBreakdown: Record<string, ScoreFactor>,
    47	  evidenceLevel: EvidenceLevel,
    48	) {
    49	  const kept = Object.entries(scoreBreakdown).filter(([name]) => name !== "future_relevance");
    50	  const weightLeft = kept.reduce((sum, [, factor]) => sum + factor.weight, 0);
    51	  if (weightLeft <= 0) return 0;
    52	  const raw = kept.reduce((sum, [, factor]) => sum + factor.value * factor.weight, 0);
    53	  return Math.round((raw / weightLeft) * 100 * CONFIDENCE[evidenceLevel] * 10) / 10;
    54	}
    55	
    56	function FactorRow({ step, maximum = 100 }: { step: WaterfallStep; maximum?: number }) {
    57	  if (step.factor === "confidence") {
    58	    return (
    59	      <div className="rounded-md border border-dashed border-slate-300 bg-slate-50 px-3 py-2">
    60	        <div className="flex items-center justify-between gap-4 text-sm">
    61	          <span className="font-semibold text-[#262626]">Evidence confidence</span>
    62	          <span className={step.contribution < 0 ? "font-semibold text-amber-700" : "font-semibold text-slate-600"}>
    63	            {step.contribution.toFixed(1)} pts
    64	          </span>
    65	        </div>
    66	        <p className="mt-1 text-xs text-slate-600">{step.sentence}</p>
    67	      </div>
    68	    );
    69	  }
    70	
    71	  const width = Math.min(100, Math.max(0, (step.contribution / Math.max(maximum, 0.01)) * 100));
    72	  return (
    73	    <div className="py-2">
    74	      <div className="flex flex-wrap items-baseline justify-between gap-x-3 gap-y-1 text-sm">
    75	        <span className="font-semibold text-[#262626]">{FACTOR_LABELS[step.factor] ?? step.label}</span>
    76	        <span className="text-slate-600">
    77	          +{step.contribution.toFixed(1)} pts
    78	        </span>
    79	      </div>
    80	      <div className="mt-2 h-2.5 w-full overflow-hidden bg-slate-200">
    81	        <div className="h-full bg-blue-600" style={{ width: `${width}%` }} />
    82	      </div>
    83	      <details className="mt-1 text-xs text-slate-600"><summary>Calculation details</summary><p className="mt-1">{step.sentence}</p>{step.weight !== null && <p>{step.value.toFixed(2)} x {step.weight.toFixed(2)} x 100</p>}</details>
    84	    </div>
    85	  );
    86	}
    87	
    88	export function ScoreWaterfall({
    89	  scoreBreakdown,
    90	  evidenceLevel,
    91	  finalScore,
    92	  waterfall,
    93	  ignoreAssumptions,
    94	  onToggleIgnoreAssumptions,
    95	}: {
    96	  scoreBreakdown: Record<string, ScoreFactor>;
    97	  evidenceLevel: EvidenceLevel;
    98	  finalScore: number;
    99	  waterfall?: WaterfallStep[];
   100	  ignoreAssumptions?: boolean;
   101	  onToggleIgnoreAssumptions?: (value: boolean) => void;
   102	}) {
   103	  const originalSteps = (waterfall?.length ? waterfall : fromBreakdown(scoreBreakdown)).filter(
   104	    (step) => step.factor !== "confidence",
   105	  );
   106	  const weightLeft = originalSteps.filter(s => s.factor !== "future_relevance").reduce((sum, s) => sum + (s.weight ?? 0), 0);
   107	  const factorSteps = ignoreAssumptions ? originalSteps.filter(s => s.factor !== "future_relevance").map(s => ({ ...s, contribution: weightLeft > 0 ? s.contribution / weightLeft : 0, weight: weightLeft > 0 ? (s.weight ?? 0) / weightLeft : 0 })) : originalSteps;
   108	  const confidenceStep = !ignoreAssumptions ? waterfall?.find((step) => step.factor === "confidence") : undefined;
   109	  const subtotal = factorSteps.reduce((sum, step) => sum + step.contribution, 0);
   110	  const scoreNoAssumptions = scoreWithoutAssumptions(scoreBreakdown, evidenceLevel);
   111	  const displayedScore = ignoreAssumptions ? scoreNoAssumptions : finalScore;
   112	  const calculatedDeduction = Math.round((displayedScore - subtotal) * 10) / 10;
   113	
   114	  return (
   115	    <section className="rounded-lg border border-slate-200 bg-white p-5 shadow-sm">
   116	      <div className="flex flex-wrap items-start justify-between gap-4">
   117	        <div>
   118	          <h2 className="text-sm font-semibold uppercase tracking-wide text-slate-500">
   119	            Why this priority?
   120	          </h2>
   121	          <p className="mt-1 text-sm text-slate-600">
   122	            Priority score / 100
   123	          </p>
   124	        </div>
   125	        <div className="flex flex-wrap items-center gap-3">
   126	          <div className="rounded-md border border-slate-200 px-3 py-2 text-right">
   127	            <p className="text-[11px] uppercase tracking-wide text-slate-500">{ignoreAssumptions ? "Preview" : "Final"}</p>
   128	            <p className="text-lg font-semibold text-[#262626]">{displayedScore.toFixed(1)}</p>
   129	          </div>
   130	          <div className="rounded-md border border-dashed border-slate-300 px-3 py-2 text-right">
   131	            <p className="text-[11px] uppercase tracking-wide text-slate-500">Without future factor</p>
   132	            <p className="text-lg font-semibold text-[#262626]">{scoreNoAssumptions.toFixed(1)}</p>
   133	          </div>
   134	        </div>
   135	      </div>
   136	
   137	      {onToggleIgnoreAssumptions && (
   138	        <label className="mt-4 flex min-h-11 items-center gap-3 rounded-md border border-dashed border-slate-300 px-3 py-2 text-sm text-slate-700">
   139	          <input
   140	            type="checkbox"
   141	            className="h-4 w-4 accent-blue-600"
   142	            checked={Boolean(ignoreAssumptions)}
   143	            onChange={(event) => onToggleIgnoreAssumptions(event.target.checked)}
   144	          />
   145	          Exclude future relevance (preview)
   146	        </label>
   147	      )}
   148	
   149	      <div className="mt-4 divide-y divide-slate-100">
   150	        {factorSteps.map((step) => (
   151	          <FactorRow key={step.factor} step={step} maximum={Math.max(...factorSteps.map(s => s.contribution), 1)} />
   152	        ))}
   153	      </div>
   154	
   155	      <div className="mt-4 grid gap-2 border-t border-slate-200 pt-3">
   156	        <div className="flex items-baseline justify-between text-sm">
   157	          <span className="text-slate-600">Subtotal before evidence confidence</span>
   158	          <span className="font-semibold text-[#262626]">{subtotal.toFixed(1)} pts</span>
   159	        </div>
   160	        {confidenceStep ? (
   161	          <FactorRow step={confidenceStep} />
   162	        ) : (
   163	          <div className="flex items-baseline justify-between text-sm">
   164	            <span className="text-slate-600">
   165	              Confidence adjustment from {EVIDENCE_LABEL[evidenceLevel]}
   166	            </span>
   167	            <span className="font-semibold text-amber-700">{calculatedDeduction.toFixed(1)} pts</span>
   168	          </div>
   169	        )}
   170	      </div>
   171	    </section>
   172	  );
   173	}
