    16	const AssistantContext = createContext<Ctx>({ open: () => {}, close: () => {} });
    17	export const useAssistant = () => useContext(AssistantContext);
    18	
    19	const GREETING: Message = {
    20	  role: "bot",
    21	  text: "Hi, I am the Signal2Spec assistant. Ask what to build first, what a label means, or where to find something. I only answer with real requirement IDs from the data.",
    22	};
    23	
    24	const toHit = (h: AskHit): Hit => ({ id: h.requirement_id, title: h.title, scenarioId: h.scenario_id, level: h.evidence_level, note: h.reasons[0]?.sentence });
    25	
    26	// Der Assistent lebt im Layout, damit der Verlauf beim Seitenwechsel erhalten bleibt.
    27	// Er navigiert selbst (router.push), statt nur Links zu nennen: im Demo spart das Klicks.
    28	export function AssistantProvider({ children }: { children: React.ReactNode }) {
    29	  const router = useRouter();
    30	  const scenarioId = useSearchParams().get("scenario") ?? DEFAULT_SCENARIO_ID;
    31	  const [isOpen, setOpen] = useState(false);
