    36	
    37	  useEffect(() => {
    38	    getScenarios().then(setScenarios).catch(() => setScenarios([]));
    39	  }, []);
    40	
    41	  useEffect(() => {
    42	    const onKey = (e: KeyboardEvent) => e.key === "Escape" && setOpen(false);
    43	    window.addEventListener("keydown", onKey);
    44	    return () => window.removeEventListener("keydown", onKey);
    45	  }, []);
    46	
    47	  const push = (m: Message) => setMessages((list) => [...list, m]);
    48	
