    50	    async (text: string) => {
    51	      if (!text.trim() || busy) return;
    52	      push({ role: "user", text: text.trim() });
    53	      const routed = routeQuestion(text, { scenarioId, scenarios });
    54	      if (routed.kind === "reply") {
    55	        push({ role: "bot", text: routed.text, links: routed.links });
    56	        if (routed.navigate) router.push(routed.navigate);
    57	        return;
    58	      }
    59	      setBusy(true);
    60	      try {
    61	        if (routed.kind === "top") {
    62	          const top = (await getRequirements(routed.scenarioId)).slice(0, 3);
    63	          push({
    64	            role: "bot",
    65	            text: top.length ? `Top of the ranked list for ${routed.scenarioId}:` : "No requirements for this scenario yet.",
    66	            hits: top.map((r) => ({ id: r.id, title: r.title, scenarioId: routed.scenarioId, level: r.evidence_level, note: `Rank ${r.rank} · score ${r.score.toFixed(1)}` })),
    67	            links: [{ href: `/cockpit?scenario=${routed.scenarioId}`, label: "Open the full list" }],
    68	          });
    69	        } else {
    70	          // Rückfall: Läuft ein älteres Backend ohne /api/ask, fragen wir die Linse des aktuellen Szenarios.
    71	          const res = await postAsk(routed.question, "pm.demo").catch(async () => {
    72	            const lens = await postLens(scenarioId, routed.question, "pm.demo");
    73	            return {
    74	              question: lens.question, source: lens.source, interpretation: lens.interpretation, answer: lens.interpretation,
    75	              top: lens.top.map((t) => ({ scenario_id: scenarioId, requirement_id: t.requirement.id, title: t.requirement.title, rank: t.requirement.rank, score: t.lens_score, lens_score: t.lens_score, evidence_level: t.requirement.evidence_level, reasons: t.reasons })),
    76	            };
    77	          });
    78	          push({
