     4	import { getFunnel, getRequirements, getScenarios, type EvidenceLevel, type Funnel, type Scenario } from "@/src/lib/api";
     5	import { DEFAULT_SCENARIO_ID } from "@/src/components/shell/scenarioLabel";
     6	
     7	export type HomeData = {
     8	  scenarios: Scenario[];
     9	  funnels: Record<string, Funnel>;
    10	  // Anzahl Anforderungen je Evidenzstufe im Hauptszenario, direkt aus dem Backend gezählt.
    11	  levels: Record<EvidenceLevel, number> | null;
    12	  // Ampel-Zählung je Szenario für die Karten (grün = A+B, gelb = C, rot = D).
    13	  levelsBy: Record<string, Record<EvidenceLevel, number>>;
    14	  // Top 15 des Hauptszenarios (Score + Stufe): daraus baut die Partikel-Szene die Rang-Balken.
    15	  bars: { score: number; level: EvidenceLevel }[];
    16	  topTitle: string | null;
    17	  mainId: string;
    18	};
    19	
    20	// Alle Zahlen der Startseite kommen aus dem Backend. Es gibt keine erfundenen Werte:
    21	// fehlt das Backend, bleibt `null` und die Seite zeigt ehrlich "–".
    22	export function useHomeData(): HomeData {
    23	  const [data, setData] = useState<HomeData>({ scenarios: [], funnels: {}, levels: null, levelsBy: {}, bars: [], topTitle: null, mainId: DEFAULT_SCENARIO_ID });
    24	
    25	  useEffect(() => {
    26	    let cancelled = false;
    27	    (async () => {
    28	      try {
    29	        const scenarios = await getScenarios();
    30	        const mainId = scenarios.find((s) => s.id === DEFAULT_SCENARIO_ID)?.id ?? scenarios[0]?.id;
    31	        if (!mainId) return;
    32	        const [funnelList, reqLists] = await Promise.all([
    33	          Promise.all(scenarios.map((s) => getFunnel(s.id).catch(() => null))),
    34	          Promise.all(scenarios.map((s) => getRequirements(s.id).catch(() => []))),
    35	        ]);
    36	        const count = (list: { evidence_level: EvidenceLevel }[]) => {
    37	          const out: Record<EvidenceLevel, number> = { A: 0, B: 0, C: 0, D: 0 };
    38	          list.forEach((r) => (out[r.evidence_level] += 1));
    39	          return out;
    40	        };
    41	        const levelsBy: Record<string, Record<EvidenceLevel, number>> = {};
    42	        scenarios.forEach((s, i) => (levelsBy[s.id] = count(reqLists[i])));
    43	        const reqs = reqLists[scenarios.findIndex((s) => s.id === mainId)] ?? [];
    44	        const bars = reqs.slice(0, 15).map((r) => ({ score: r.score, level: r.evidence_level }));
    45	        const funnels: Record<string, Funnel> = {};
    46	        scenarios.forEach((s, i) => {
    47	          const f = funnelList[i];
    48	          if (f) funnels[s.id] = f;
    49	        });
    50	        const levels = count(reqs);
    51	        if (!cancelled) {
    52	          setData({ scenarios, funnels, levels: reqs.length ? levels : null, levelsBy, bars, topTitle: reqs[0]?.title ?? null, mainId });
    53	        }
    54	      } catch {
    55	        /* Backend aus: Seite bleibt mit "–" nutzbar */
    56	      }
    57	    })();
    58	    return () => {
    59	      cancelled = true;
    60	    };
    61	  }, []);
