     1	"use client";
     2	
     3	import { useEffect, useRef, useState } from "react";
     4	
     5	type Manifest = { count: number; pattern: string; width: number; height: number };
     6	export type FrameStatus = "loading" | "ready" | "fallback";
     7	
     8	function frameUrl(m: Manifest, i: number) {
     9	  return m.pattern.replace("%04d", String(i + 1).padStart(4, "0"));
    10	}
    11	
    12	// Lädt die Auto-Frames progressiv: erst jedes 4. Bild (schnell sichtbar), dann die Lücken.
    13	// Auf dem Handy (< 768 px) nur jedes 2. Bild, das spart Daten und Speicher.
    14	export function useCarFrames() {
    15	  const frames = useRef<(HTMLImageElement | undefined)[]>([]);
    16	  const manifest = useRef<Manifest | null>(null);
    17	  const [state, setState] = useState<{ status: FrameStatus; progress: number }>({ status: "loading", progress: 0 });
    18	
    19	  useEffect(() => {
    20	    let cancelled = false;
    21	
    22	    async function load(m: Manifest) {
    23	      const stride = window.innerWidth < 768 ? 2 : 1;
    24	      const wanted: number[] = [];
    25	      for (let i = 0; i < m.count; i += stride) wanted.push(i);
    26	      const first = wanted.filter((_, k) => k % 4 === 0);
    27	      const rest = wanted.filter((_, k) => k % 4 !== 0);
    28	
    29	      const fetchOne = (i: number) =>
    30	        new Promise<void>((resolve) => {
    31	          const img = new Image();
    32	          img.onload = () => {
    33	            frames.current[i] = img;
    34	            resolve();
    35	          };
    36	          img.onerror = () => resolve();
    37	          img.src = frameUrl(m, i);
    38	        });
    39	
    40	      let done = 0;
    41	      const run = async (list: number[], report: boolean) => {
    42	        let next = 0;
    43	        const worker = async () => {
    44	          while (!cancelled && next < list.length) {
    45	            await fetchOne(list[next++]);
    46	            if (report && !cancelled) {
    47	              done += 1;
    48	              setState({ status: "loading", progress: done / list.length });
    49	            }
    50	          }
    51	        };
    52	        await Promise.all(Array.from({ length: 6 }, worker));
    53	      };
    54	
    55	      await run(first, true);
    56	      if (cancelled) return;
    57	      setState({ status: frames.current.some(Boolean) ? "ready" : "fallback", progress: 1 });
    58	      await run(rest, false);
    59	    }
    60	
    61	    fetch("/media-manifest")
    62	      .then((r) => r.json())
    63	      .then((data) => {
    64	        if (cancelled) return;
    65	        if (!data.available || !data.count) {
    66	          setState({ status: "fallback", progress: 1 });
    67	          return;
    68	        }
    69	        manifest.current = data as Manifest;
    70	        return load(data as Manifest);
    71	      })
    72	      .catch(() => !cancelled && setState({ status: "fallback", progress: 1 }));
    73	
    74	    return () => {
    75	      cancelled = true;
    76	    };
    77	  }, []);
    78	
    79	  return { frames, manifest, ...state };
    80	}
