     1	"use client";
     2	
     3	// Lädt GSAP (ScrollTrigger) und Lenis erst auf der Startseite per dynamic import.
     4	// Warum: Das Cockpit ist ein Datenwerkzeug mit nativem Scrollen und soll leicht bleiben.
     5	type Engine = {
     6	  gsap: typeof import("gsap").gsap;
     7	  ScrollTrigger: typeof import("gsap/ScrollTrigger").ScrollTrigger;
     8	};
     9	
    10	let pending: Promise<Engine> | null = null;
    11	let users = 0;
    12	let teardown: (() => void) | null = null;
    13	
    14	export function acquireScrollEngine(): Promise<Engine> {
    15	  users += 1;
    16	  if (!pending) {
    17	    pending = (async () => {
    18	      const [{ gsap }, { ScrollTrigger }, { default: Lenis }] = await Promise.all([
    19	        import("gsap"),
    20	        import("gsap/ScrollTrigger"),
    21	        import("lenis"),
    22	      ]);
    23	      gsap.registerPlugin(ScrollTrigger);
    24	      const lenis = new Lenis({ lerp: 0.1 });
    25	      lenis.on("scroll", ScrollTrigger.update);
    26	      const tick = (time: number) => lenis.raf(time * 1000);
    27	      gsap.ticker.add(tick);
    28	      gsap.ticker.lagSmoothing(0);
    29	      teardown = () => {
    30	        gsap.ticker.remove(tick);
    31	        lenis.destroy();
    32	      };
    33	      return { gsap, ScrollTrigger };
    34	    })();
    35	  }
    36	  return pending;
    37	}
    38	
    39	export function releaseScrollEngine() {
    40	  users -= 1;
    41	  if (users <= 0) {
    42	    teardown?.();
    43	    teardown = null;
    44	    pending = null;
    45	    users = 0;
    46	  }
    47	}
