// Tests für die Modell- und Regionsauswahl im Marktvergleich. Start: node --test src/components/portfolio/compareModels.test.mjs
// Wie intents.test.mjs: Node-Test-Runner + vorhandenes "typescript" zum Übersetzen, keine neue Abhängigkeit.
import { test } from "node:test";
import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import ts from "typescript";

const source = readFileSync(new URL("./compareModels.ts", import.meta.url), "utf8");
const { outputText } = ts.transpileModule(source, { compilerOptions: { module: ts.ModuleKind.ESNext, target: ts.ScriptTarget.ES2022 } });
const { comparableModels, pickMarkets } = await import(`data:text/javascript,${encodeURIComponent(outputText)}`);

const s = (id, derivative, market) => ({ id, derivative, market, model_name: `BMW (${derivative})` });
const ALL = [
  s("F70-EU", "F70", "EU"),
  s("G60-EU", "G60", "EU"),
  s("G60-US", "G60", "US"),
  s("G68-CN", "G68", "CN"),
  s("G70-EU", "G70", "EU"),
  s("G70-US", "G70", "US"),
];

test("Nur Modelle mit mindestens zwei Regionen sind wählbar", () => {
  const models = comparableModels(ALL);
  assert.deepEqual(models.map((m) => m.derivative), ["G60", "G70"]);
  assert.deepEqual(models[0].markets, [{ market: "EU", scenarioId: "G60-EU" }, { market: "US", scenarioId: "G60-US" }]);
  assert.equal(models[0].label, "BMW (G60)");
});

test("Ohne Modell mit mehreren Regionen gibt es nichts zu vergleichen", () => {
  assert.deepEqual(comparableModels([s("F70-EU", "F70", "EU"), s("G60-US", "G60", "US")]), []);
});

test("Doppelte Region im selben Modell zählt nur einmal", () => {
  assert.deepEqual(comparableModels([s("G60-US", "G60", "US"), s("G60-US2", "G60", "US")]), []);
});

test("Regionen-Paar ist immer verschieden", () => {
  const markets = ["EU", "US", "CN"];
  assert.deepEqual(pickMarkets(markets, "", ""), ["EU", "US"]);
  assert.deepEqual(pickMarkets(markets, "CN", ""), ["CN", "EU"]);
  assert.deepEqual(pickMarkets(markets, "US", "US"), ["US", "EU"]);
  assert.deepEqual(pickMarkets(markets, "XX", "CN"), ["EU", "CN"]);
});

import type { Scenario } from "@/src/lib/api";

// Reine Auswahl-Logik für "Compare two markets", getrennt von der Oberfläche, damit sie testbar ist.
// Warum nur dasselbe Modell: Ein Regionsvergleich ist nur fair, wenn dasselbe Auto in beiden Märkten steht
// (z. B. G60 EU gegen G60 US). Modell gegen Modell würde Markt- und Modellunterschiede vermischen.

export interface ComparableModel {
  derivative: string;
  label: string;
  markets: { market: string; scenarioId: string }[];
}

// Modelle mit mindestens zwei verschiedenen Regionen, in der Reihenfolge der API.
export function comparableModels(scenarios: Pick<Scenario, "id" | "derivative" | "market" | "model_name">[]): ComparableModel[] {
  const byModel = new Map<string, ComparableModel>();
  for (const s of scenarios) {
    const model = byModel.get(s.derivative) ?? { derivative: s.derivative, label: s.model_name, markets: [] };
    if (!model.markets.some((m) => m.market === s.market)) model.markets.push({ market: s.market, scenarioId: s.id });
    byModel.set(s.derivative, model);
  }
  return [...byModel.values()].filter((m) => m.markets.length >= 2);
}

// Liefert immer zwei verschiedene Regionen: ungültige oder doppelte Wahl fällt auf die erste freie Region zurück.
// Erwartet mindestens zwei Regionen (garantiert durch comparableModels).
export function pickMarkets(markets: string[], wantedA: string, wantedB: string): [string, string] {
  const a = markets.includes(wantedA) ? wantedA : markets[0];
  const b = markets.includes(wantedB) && wantedB !== a ? wantedB : markets.find((m) => m !== a)!;
  return [a, b];
}

